from __future__ import annotations

from typing import Any

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    config = _read_config(raw)
    if isinstance(config, dict):
        return config

    width, height, cell_size, fill_value, mode, observations, grid_width, grid_height, edge = config
    totals: dict[tuple[int, int], int] = {}
    maxima: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in observations:
        field = _validated_observation(obs)
        if field is None:
            return {"ok": False, "error": "bad observation"}
        x, y, value, quality = field

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        key = _cell(x, y, cell_size, width, height, grid_width, grid_height, edge)
        if key is None:
            dropped += 1
            continue
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        totals[key] = totals.get(key, 0) + value
        maxima[key] = max(maxima.get(key, value), value)
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _filled_rows(mode, totals, maxima, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    total_cells = width * height
    line = _summary_line(total_cells, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _read_config(raw: object) -> tuple | dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    missing = {"grid", "observations", "fill_value"} - set(raw)
    if missing:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    missing = {"width", "height", "cell_size"} - set(grid)
    if missing:
        return {"ok": False, "error": "bad grid"}
    checked = (
        _checked_dim(grid["width"], MAX_DIM, "bad width"),
        _checked_dim(grid["height"], MAX_DIM, "bad height"),
        _checked_positive(grid["cell_size"]),
        _checked_int(raw["fill_value"], "bad fill value"),
    )
    for item in checked:
        if isinstance(item, dict):
            return item
    width, height, cell_size, fill_value = checked
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}
    return (
        width,
        height,
        cell_size,
        fill_value,
        mode,
        observations,
        width * cell_size,
        height * cell_size,
        cell_size // 2,
    )


def _checked_dim(value: Any, max_dim: int, label: str) -> int | dict:
    if not isinstance(value, int) or value < 1 or value > max_dim:
        return {"ok": False, "error": label}
    return value


def _checked_positive(value: Any) -> int | dict:
    if not isinstance(value, int) or value < 1:
        return {"ok": False, "error": "bad cell size"}
    return value


def _checked_int(value: Any, label: str) -> int | dict:
    if not isinstance(value, int):
        return {"ok": False, "error": label}
    return value


def _validated_observation(obs: object) -> tuple[int, int, int, int] | None:
    if not isinstance(obs, dict):
        return None
    x = obs.get("x")
    y = obs.get("y")
    value = obs.get("value")
    quality = obs.get("quality")
    if (
        not isinstance(x, int)
        or not isinstance(y, int)
        or not isinstance(value, int)
        or not isinstance(quality, int)
        or quality < 0
        or quality > 100
    ):
        return None
    return x, y, value, quality


def _cell(x: int, y: int, cell_size: int, width: int, height: int, grid_width: int, grid_height: int, edge: int) -> tuple[int, int] | None:
    col = _axis_index(x, cell_size, width, grid_width, edge)
    if col is None:
        return None
    row = _axis_index(y, cell_size, height, grid_height, edge)
    if row is None:
        return None
    return (row, col)


def _axis_index(coord: int, cell_size: int, dim: int, extent: int, edge: int) -> int | None:
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dim and coord - extent >= edge:
        return None
    if index >= dim:
        index = dim - 1
    return index


def _filled_rows(mode: str, totals: dict, maxima: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                if mode == "max":
                    cells.append(maxima[key])
                else:
                    cells.append(totals[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_FIELDS = ("grid", "observations", "fill_value")
_GRID_FIELDS = ("width", "height", "cell_size")
_OB_KEYS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}

    width = _PARSED["grid"]["width"]
    height = _PARSED["grid"]["height"]
    cell_size = _PARSED["grid"]["cell_size"]
    fill_value = _PARSED["fill_value"]
    mode = _PARSED.get("mode", "mean")

    result = _accumulate(_PARSED["observations"], width, height, cell_size)
    if result is None:
        return {"ok": False, "error": "bad observation"}
    sums, counts, maxes, degraded, stats = result

    cells = _cell_rows(sums, counts, maxes, width, height, fill_value, mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(
        width * height,
        len(counts),
        stats["dropped"],
        stats["rejected"],
        stats["saturated"],
        coverage,
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": stats["dropped"],
        "rejected": stats["rejected"],
        "saturated": stats["saturated"],
        "coverage": coverage,
        "line": line,
    }


_PARSED: dict = {}


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if not all(field in raw for field in _FIELDS):
        return "missing field"

    grid_error = _validate_grid(raw["grid"])
    if grid_error is not None:
        return grid_error
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    if not isinstance(raw["observations"], list):
        return "bad observations"

    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return "bad mode"

    _PARSED["grid"] = raw["grid"]
    _PARSED["fill_value"] = raw["fill_value"]
    _PARSED["observations"] = raw["observations"]
    _PARSED["mode"] = mode
    return None


def _validate_grid(grid: object) -> str | None:
    if not isinstance(grid, dict):
        return "bad grid"
    if not all(field in grid for field in _GRID_FIELDS):
        return "bad grid"
    if not _valid_dim(grid["width"]):
        return "bad width"
    if not _valid_dim(grid["height"]):
        return "bad height"
    if not _valid_cell_size(grid["cell_size"]):
        return "bad cell size"
    return None


def _valid_dim(value: object) -> bool:
    return isinstance(value, int) and 1 <= value <= MAX_DIM


def _valid_cell_size(value: object) -> bool:
    return isinstance(value, int) and value >= 1


def _accumulate(
    observations: list, width: int, height: int, cell_size: int
) -> tuple[dict, dict, dict, dict, dict] | None:
    sums: dict = {}
    counts: dict = {}
    maxes: dict = {}
    degraded: dict = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if not _valid_observation(obs):
            return None
        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        key = _project(obs, width, height, cell_size, tolerance)
        if key is None:
            dropped += 1
            continue
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue

        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        maxes[key] = max(maxes.get(key, 0), obs["value"])
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    return (
        sums,
        counts,
        maxes,
        degraded,
        {"dropped": dropped, "rejected": rejected, "saturated": saturated},
    )


def _valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    for key in _OB_KEYS:
        if key not in obs or not isinstance(obs[key], int):
            return False
    return 0 <= obs["quality"] <= 100


def _project(
    obs: dict, width: int, height: int, cell_size: int, tolerance: int
) -> tuple | None:
    x = obs["x"]
    if x < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
        else:
            return None

    y = obs["y"]
    if y < 0:
        return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
        else:
            return None

    return (row, col)


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _maxed_rows(maxes: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(maxes[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _cell_rows(sums, counts, maxes, width, height, fill_value, mode):
    if mode == "max":
        return _maxed_rows(maxes, counts, width, height, fill_value)
    return _averaged_rows(sums, counts, width, height, fill_value)


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

from collections.abc import Mapping

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, Mapping):
        return {"ok": False, "error": "malformed input"}

    grid = raw.get("grid")
    observations = raw.get("observations")
    fill_value = raw.get("fill_value")
    if grid is None or observations is None or fill_value is None:
        return {"ok": False, "error": "missing field"}

    mode = raw.get("mode")
    if mode is None:
        mode = "mean"
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    if not isinstance(grid, Mapping):
        return {"ok": False, "error": "bad grid"}

    width = grid.get("width")
    height = grid.get("height")
    cell_size = grid.get("cell_size")
    if width is None or height is None or cell_size is None:
        return {"ok": False, "error": "bad grid"}

    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(fill_value, int):
        return {"ok": False, "error": "bad fill value"}
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    maxes: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    max_col = width - 1
    max_row = height - 1
    width_edge = width * cell_size
    height_edge = height * cell_size

    for obs in observations:
        if not isinstance(obs, Mapping):
            return {"ok": False, "error": "bad observation"}

        x = obs.get("x")
        y = obs.get("y")
        value = obs.get("value")
        quality = obs.get("quality")
        if (
            not isinstance(x, int)
            or not isinstance(y, int)
            or not isinstance(value, int)
            or not isinstance(quality, int)
            or quality < 0
            or quality > 100
        ):
            return {"ok": False, "error": "bad observation"}

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        if x < 0:
            dropped += 1
            continue
        col = x // cell_size
        if col > max_col:
            if x - width_edge < tolerance:
                col = max_col
            else:
                dropped += 1
                continue

        if y < 0:
            dropped += 1
            continue
        row = y // cell_size
        if row > max_row:
            if y - height_edge < tolerance:
                row = max_row
            else:
                dropped += 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        maxes[key] = max(maxes.get(key, value), value)
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _cell_rows(sums, maxes, counts, mode, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(len(counts), width * height)
    line = _summary_line(
        width * height, len(counts), dropped, rejected, saturated, coverage
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _cell_rows(
    sums: dict[tuple[int, int], int],
    maxes: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    mode: str,
    width: int,
    height: int,
    fill_value: int,
) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                cells.append(fill_value)
            elif mode == "max":
                cells.append(maxes[key])
            else:
                cells.append(sums[key] // counts[key])
        rows.append(cells)
    return rows


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: set[tuple[int, int]],
    width: int,
    height: int,
) -> list:
    rows = []
    for row in range(height):
        flags = [
            "empty" if (row, col) not in counts
            else "degraded" if (row, col) in degraded
            else "good"
            for col in range(width)
        ]
        rows.append(flags)
    return rows


def _coverage(filled: int, total_cells: int) -> int:
    return filled * 100 // total_cells


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        f"cells={total_cells};"
        f"filled={filled};"
        f"dropped={dropped};"
        f"rejected={rejected};"
        f"saturated={saturated};"
        f"coverage={coverage}"
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object, mode: str = "mean") -> dict:
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}

    grid = raw["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    tolerance = cell_size // 2
    observations = raw["observations"]

    sums = {}
    maxs = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    for obs in observations:
        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        col, keep = _to_index(obs["x"], cell_size, width, tolerance)
        if not keep:
            dropped += 1
            continue
        row, keep = _to_index(obs["y"], cell_size, height, tolerance)
        if not keep:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        maxs[key] = max(maxs.get(key, obs["value"]), obs["value"])
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    if mode == "max":
        cells = _max_rows(maxs, counts, width, height, raw["fill_value"])
    else:
        cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _to_index(value: int, cell_size: int, limit: int, tolerance: int) -> tuple[int, bool]:
    if value < 0:
        return 0, False
    index = value // cell_size
    if index >= limit and value - limit * cell_size >= tolerance:
        return 0, False
    return min(index, limit - 1), True


def _checked_observation(obs: object) -> str | None:
    if not isinstance(obs, dict):
        return "bad observation"
    for field in ("x", "y", "value", "quality"):
        if field not in obs or not isinstance(obs[field], int):
            return "bad observation"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return "bad observation"
    return None


def _checked_grid_dimension(value: object, max_value: int | None, error: str) -> str | None:
    if not isinstance(value, int) or value < 1:
        return error
    if max_value is not None and value > max_value:
        return error
    return None


def _checked_grid(grid: object) -> str | None:
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"
    for value, max_value, error in (
        (grid["width"], MAX_DIM, "bad width"),
        (grid["height"], MAX_DIM, "bad height"),
        (grid["cell_size"], None, "bad cell size"),
    ):
        cell_error = _checked_grid_dimension(value, max_value, error)
        if cell_error is not None:
            return cell_error
    return None


def _checked_observations(observations: object) -> str | None:
    if not isinstance(observations, list):
        return "bad observations"
    for obs in observations:
        error = _checked_observation(obs)
        if error is not None:
            return error
    return None


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"
    error = _checked_grid(raw["grid"])
    if error is not None:
        return error
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    return _checked_observations(raw["observations"])


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _max_rows(maxs: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(maxs[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
