GOOD_QUALITY = 60
SATURATION_LIMIT = 5

ERR_MALFORMED = "malformed input"
ERR_MISSING_FIELD = "missing field"
ERR_BAD_GRID = "bad grid"
ERR_BAD_WIDTH = "bad width"
ERR_BAD_HEIGHT = "bad height"
ERR_BAD_CELL_SIZE = "bad cell size"
ERR_BAD_FILL = "bad fill value"
ERR_BAD_OBSERVATIONS = "bad observations"
ERR_BAD_OBSERVATION = "bad observation"
ERR_BAD_MODE = "bad mode"
_OBS_FIELDS = ("x", "y", "value", "quality")


def _observation_error(obs: object) -> str | None:
    if not isinstance(obs, dict):
        return ERR_BAD_OBSERVATION
    for field in _OBS_FIELDS:
        if field not in obs or not isinstance(obs[field], int):
            return ERR_BAD_OBSERVATION
    if not 0 <= obs["quality"] <= 100:
        return ERR_BAD_OBSERVATION
    return None


def _cell_for(x: int, y: int, width: int, height: int, cell_size: int,
               tolerance: int) -> tuple[int, int] | None:
    if x < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size >= tolerance:
            return None
        col = width - 1
    if y < 0:
        return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size >= tolerance:
            return None
        row = height - 1
    return row, col


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": ERR_MALFORMED}
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": ERR_BAD_MODE}
    if not all(k in raw for k in ("grid", "observations", "fill_value")):
        return {"ok": False, "error": ERR_MISSING_FIELD}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": ERR_BAD_GRID}
    if not all(k in grid for k in ("width", "height", "cell_size")):
        return {"ok": False, "error": ERR_BAD_GRID}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or not 1 <= width <= MAX_DIM:
        return {"ok": False, "error": ERR_BAD_WIDTH}
    if not isinstance(height, int) or not 1 <= height <= MAX_DIM:
        return {"ok": False, "error": ERR_BAD_HEIGHT}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": ERR_BAD_CELL_SIZE}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": ERR_BAD_FILL}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": ERR_BAD_OBSERVATIONS}

    sums: dict[tuple[int, int], int] = {}
    maxima: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        error = _observation_error(obs)
        if error is not None:
            return {"ok": False, "error": error}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        cell = _cell_for(obs["x"], obs["y"], width, height, cell_size, tolerance)
        if cell is None:
            dropped += 1
            continue

        if counts.get(cell, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[cell] = sums.get(cell, 0) + obs["value"]
        maxima[cell] = max(maxima.get(cell, obs["value"]), obs["value"])
        counts[cell] = counts.get(cell, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(cell)

    if mode == "max":
        cells = _filled_rows(maxima, counts, width, height, raw["fill_value"])
    else:
        cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(sums: dict, counts: dict, width: int, height: int,
                   fill_value: int) -> list:
    return [
        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _filled_rows(values: dict, counts: dict, width: int, height: int,
                 fill_value: int) -> list:
    return [
        [values[(row, col)] if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    return [
        ["empty" if (row, col) not in counts
         else "degraded" if (row, col) in degraded else "good"
         for col in range(width)]
        for row in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int,
                  saturated: int, coverage: int) -> str:
    return (
        f"cells={total_cells};"
        f"filled={filled};"
        f"dropped={dropped};"
        f"rejected={rejected};"
        f"saturated={saturated};"
        f"coverage={coverage}"
    )

