    "id": lambda v: isinstance(v, str),
    "name": lambda v: isinstance(v, str) and len(v) > 0,
    "age": lambda v: isinstance(v, int) and v >= 0,
    "email": lambda v: isinstance(v, str) and "@" in v,
}


