    if raw is None or not isinstance(raw, dict) or not _is_valid_record(raw):
        return DEFAULT

    result = {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }
    if "phone" in raw:
        result["phone"] = raw["phone"]
    return result

