def _default_record() -> dict:
    return dict(DEFAULT)


def _valid_email(email: object) -> bool:
    if not isinstance(email, str):
        return False
    if email.count("@") != 1:
        return False
    local, domain = email.rsplit("@", 1)
    return bool(local) and bool(domain)


def _valid_name(name: object) -> bool:
    return isinstance(name, str) and len(name) > 0


def _valid_age(age: object) -> bool:
    return isinstance(age, int) and not isinstance(age, bool) and age >= 0


def _valid_id(identifier: object) -> bool:
    return isinstance(identifier, str)


FIELD_CHECKS = {
    "id": _valid_id,
    "name": _valid_name,
    "age": _valid_age,
    "email": _valid_email,
}


def _valid_phone(phone: object) -> bool:
    return isinstance(phone, str) and len(phone) == 10 and phone.isdigit()


def _valid_payload(payload: dict) -> bool:
    if not all(key in payload for key in REQUIRED_KEYS):
        return False
    if not all(check(payload[key]) for key, check in FIELD_CHECKS.items()):
        return False
    if "phone" in payload and not _valid_phone(payload["phone"]):
        return False
    return True


def parse_record(raw: object) -> dict:
    if not isinstance(raw, dict) or not _valid_payload(raw):
        return _default_record()
    result = {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }
    if "phone" in raw:
        result["phone"] = raw["phone"]
    return result

