    return isinstance(value, str) and len(value) > 0


def _looks_like_email(value: object) -> bool:
    return isinstance(value, str) and "@" in value


def _is_valid_record(raw: dict) -> bool:
    return (
        isinstance(raw["id"], str)
        and _is_nonempty_str(raw["name"])
        and _is_nonnegative_int(raw["age"])
        and _looks_like_email(raw["email"])
    )


