        return {"ok": False, "error": "bad fill value"}
    if not isinstance(raw["observations"], list):
        return {"ok": False, "error": "bad observations"}
    if "mode" in raw and raw["mode"] not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    return grid, width, height, cell_size, raw["observations"]


def _fold(observations: list, cell_size: int, width: int, height: int) -> dict | tuple:
    sums = {}
    counts = {}
    degraded = {}
    maxes = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if _validate_observation(obs):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        cell = _to_cell(obs["x"], obs["y"], width, height, cell_size, tolerance)
        if cell is None:
            dropped += 1
            continue

        if counts.get(cell, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[cell] = sums.get(cell, 0) + obs["value"]
        counts[cell] = counts.get(cell, 0) + 1
        maxes[cell] = max(maxes.get(cell, obs["value"]), obs["value"])
        if obs["quality"] < GOOD_QUALITY:
            degraded[cell] = True
    return sums, counts, degraded, dropped, rejected, saturated, maxes


def _validate_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return True
    for key in _OBS_KEYS:
        if key not in obs or not isinstance(obs[key], int):
            return True
    return not (0 <= obs["quality"] <= 100)


def _to_cell(x: int, y: int, width: int, height: int, cell_size: int, tolerance: int) -> tuple[int, int] | None:
    col = _axis_cell(x, width, cell_size, tolerance)
    if col is None:
        return None
    row = _axis_cell(y, height, cell_size, tolerance)
    if row is None:
        return None
    return row, col


def _axis_cell(coord: int, dim: int, cell_size: int, tolerance: int) -> int | None:
    if coord < 0:
        return None
    cell = coord // cell_size
    if cell >= dim and coord - dim * cell_size >= tolerance:
        return None
    return min(cell, dim - 1)


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value for col in range(width)]
        for row in range(height)
    ]


def _max_rows(maxes: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [maxes[(row, col)] if (row, col) in counts else fill_value for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    def flag(key: tuple) -> str:
        if key not in counts:
            return "empty"
        return "degraded" if key in degraded else "good"

    return [[flag((row, col)) for col in range(width)] for row in range(height)]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

