from __future__ import annotations

DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

_REQUIRED_KEYS = ("id", "name", "age", "email")

VALIDATE = {
    "id": lambda v: isinstance(v, str) and len(v) > 0,
    "name": lambda v: isinstance(v, str) and len(v) > 0,
    "age": lambda v: isinstance(v, int) and not isinstance(v, bool) and v >= 0,
    "email": lambda v: isinstance(v, str) and "@" in v,
}


def _phone_ok(v: object) -> bool:
    return isinstance(v, str) and len(v) == 10 and v.isdigit()


def _blank() -> dict:
    return dict(DEFAULT)


def _offset(raw: dict) -> dict | None:
    if not all(key in raw for key in _REQUIRED_KEYS):
        return None
    for key, check in VALIDATE.items():
        if not check(raw[key]):
            return None
    if "phone" in raw and not _phone_ok(raw["phone"]):
        return None
    return {**raw, "valid": True}


def parse_record(raw: object) -> dict:
    if not isinstance(raw, dict) or raw is None:
        return _blank()
    return _offset(raw) or _blank()

from __future__ import annotations

from typing import Any

DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")


def _invalid() -> dict[str, Any]:
    return DEFAULT.copy()


def parse_record(raw: object) -> dict:
    if not isinstance(raw, dict):
        return _invalid()
    if not all(key in raw for key in REQUIRED_KEYS):
        return _invalid()
    if not isinstance(raw["id"], str):
        return _invalid()
    if not isinstance(raw["name"], str) or not raw["name"]:
        return _invalid()
    if not isinstance(raw["age"], int) or raw["age"] < 0:
        return _invalid()
    if not isinstance(raw["email"], str) or "@" not in raw["email"]:
        return _invalid()

    phone = raw.get("phone")
    if phone is not None:
        if not isinstance(phone, str) or len(phone) != 10 or not phone.isdigit():
            return _invalid()

    result = {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }
    if phone is not None:
        result["phone"] = phone
    return result

from __future__ import annotations

from typing import Any

DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")


def _invalid() -> dict:
    return DEFAULT.copy()


def _valid_phone(phone: Any) -> bool:
    return isinstance(phone, str) and len(phone) == 10 and phone.isdigit()


def _is_valid(raw: Any) -> bool:
    try:
        valid_id = isinstance(raw["id"], str)
        valid_name = isinstance(raw["name"], str) and bool(raw["name"])
        valid_age = isinstance(raw["age"], int) and raw["age"] >= 0
        valid_email = isinstance(raw["email"], str) and ("@" in raw["email"])
    except KeyError:
        return False
    if not (valid_id and valid_name and valid_age and valid_email):
        return False
    if "phone" in raw:
        return _valid_phone(raw["phone"])
    return True


def parse_record(raw: object) -> dict:
    if not isinstance(raw, dict) or not _is_valid(raw):
        return _invalid()

    id_ = raw["id"]
    name = raw["name"]
    age = raw["age"]
    email = raw["email"]
    result = {"id": id_, "name": name, "age": age, "email": email, "valid": True}
    if "phone" in raw:
        result["phone"] = raw["phone"]
    return result

from __future__ import annotations

DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")

PHONE_KEY = "phone"


def _invalid() -> dict:
    return dict(DEFAULT)


def parse_record(raw: object) -> dict:
    if not _is_valid_record(raw):
        return _invalid()

    result = {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
    }
    if PHONE_KEY in raw:
        result[PHONE_KEY] = raw[PHONE_KEY]
    result["valid"] = True
    return result


def _is_valid_record(raw: object) -> bool:
    if not isinstance(raw, dict):
        return False
    if not all(key in raw for key in REQUIRED_KEYS):
        return False
    if not isinstance(raw["id"], str):
        return False
    if not isinstance(raw["name"], str) or len(raw["name"]) == 0:
        return False
    if not isinstance(raw["age"], int):
        return False
    if raw["age"] < 0:
        return False
    if not isinstance(raw["email"], str) or "@" not in raw["email"]:
        return False
    if PHONE_KEY in raw and (
        not isinstance(raw[PHONE_KEY], str)
        or len(raw[PHONE_KEY]) != 10
        or not raw[PHONE_KEY].isdigit()
    ):
        return False
    return True

