export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type BookingRequest = Record<string, unknown>;

interface RoomTypeConfig {
  name: "standard" | "suite" | "villa" | "cabin";
  maxNights: number;
  maxGuests: number;
  baseRate: number;
  highSeasonSurcharge: number;
  minStay?: number;
  extraGuestFee?: number;
  serviceFee?: number;
}

const ROOM_TYPES: Record<string, RoomTypeConfig> = {
  standard: {
    name: "standard",
    maxNights: 14,
    maxGuests: 2,
    baseRate: 80,
    highSeasonSurcharge: 30,
  },
  suite: {
    name: "suite",
    maxNights: 21,
    maxGuests: 4,
    baseRate: 150,
    highSeasonSurcharge: 60,
    extraGuestFee: 25,
  },
  villa: {
    name: "villa",
    maxNights: 28,
    maxGuests: 8,
    baseRate: 300,
    highSeasonSurcharge: 120,
    minStay: 3,
    serviceFee: 500,
  },
  cabin: {
    name: "cabin",
    maxNights: 10,
    maxGuests: 6,
    baseRate: 50,
    highSeasonSurcharge: 15,
  },
};

function isInt(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value);
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as BookingRequest;

  const loyaltyYears = req.loyaltyYears;
  if (!isInt(loyaltyYears) || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const config = typeof req.category === "string" ? ROOM_TYPES[req.category] : undefined;
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights;
  if (!isInt(nights) || nights < 1 || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (config.minStay !== undefined && nights < config.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = req.guests;
  if (!isInt(guests) || guests < 1 || guests > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  const season = req.season;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const coupon = req.coupon;
  const isVip = coupon === "VIP";
  const isLoyal = loyaltyYears >= 3;

  let total = config.baseRate * nights + (season === "high" ? config.highSeasonSurcharge * nights : 0);
  if (isVip || isLoyal) {
    total -= Math.floor(total / 10);
  }
  if (config.extraGuestFee !== undefined && guests > 2) {
    total += config.extraGuestFee;
  }
  if (config.serviceFee !== undefined) {
    total += config.serviceFee;
  }

  const policy = isVip || isLoyal ? "flex" : "strict";
  const line = `${config.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa" | "cabin";

interface CategoryConfig {
  maxNights: number;
  maxGuests: number;
  minStay: number;
  ratePerNight: number;
  highNightSurcharge: number;
  flatSurcharge: number;
  guestSurcharge: number;
  guestThreshold: number;
}

const CATEGORIES: Record<Category, CategoryConfig> = {
  standard: {
    maxNights: 14,
    maxGuests: 2,
    minStay: 1,
    ratePerNight: 80,
    highNightSurcharge: 30,
    flatSurcharge: 0,
    guestSurcharge: 0,
    guestThreshold: Infinity,
  },
  suite: {
    maxNights: 21,
    maxGuests: 4,
    minStay: 1,
    ratePerNight: 150,
    highNightSurcharge: 60,
    flatSurcharge: 0,
    guestSurcharge: 25,
    guestThreshold: 2,
  },
  villa: {
    maxNights: 28,
    maxGuests: 8,
    minStay: 3,
    ratePerNight: 300,
    highNightSurcharge: 120,
    flatSurcharge: 500,
    guestSurcharge: 0,
    guestThreshold: Infinity,
  },
  cabin: {
    maxNights: 10,
    maxGuests: 6,
    minStay: 1,
    ratePerNight: 50,
    highNightSurcharge: 15,
    flatSurcharge: 0,
    guestSurcharge: 0,
    guestThreshold: Infinity,
  },
};

function isElite(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears >= 3 || coupon === "VIP";
}

function isInt(value: unknown): value is number {
  return Number.isInteger(value);
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!isInt(req.loyaltyYears) || req.loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cfg = CATEGORIES[req.category as Category];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  if (!isInt(req.nights) || req.nights < 1 || req.nights > cfg.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (req.nights < cfg.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!isInt(req.guests) || req.guests < 1 || req.guests > cfg.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const elite = isElite(req.loyaltyYears, req.coupon);
  const extra = req.season === "high" ? cfg.highNightSurcharge : 0;
  let total = req.nights * (cfg.ratePerNight + extra);
  if (elite) {
    total -= Math.floor(total / 10);
  }
  if (req.guests > cfg.guestThreshold) {
    total += cfg.guestSurcharge;
  }
  total += cfg.flatSurcharge;

  const policy = elite ? "flex" : "strict";
  const line = `${req.category}:${req.nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface BookingRequest {
  loyaltyYears: number;
  nights: number;
  guests: number;
  season: "low" | "high";
  coupon: string;
}

interface CategoryConfig {
  label: string;
  rate: number;
  highIncrement: number;
  maxNights: number;
  maxGuests: number;
  minStay?: number;
  discounted: (req: BookingRequest) => boolean;
  flexible: (req: BookingRequest) => boolean;
  extraFee: (guests: number) => number;
}

const VIP = "VIP";

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    label: "standard",
    rate: 80,
    highIncrement: 30,
    maxNights: 14,
    maxGuests: 2,
    discounted: (r) => r.loyaltyYears >= 3 || r.coupon === VIP,
    flexible: (r) => r.coupon === VIP || r.loyaltyYears > 2,
    extraFee: () => 0,
  },
  suite: {
    label: "suite",
    rate: 150,
    highIncrement: 60,
    maxNights: 21,
    maxGuests: 4,
    discounted: (r) => r.coupon === VIP || r.loyaltyYears >= 3,
    flexible: (r) => r.loyaltyYears >= 3 || r.coupon === VIP,
    extraFee: (guests) => (guests > 2 ? 25 : 0),
  },
  cabin: {
    label: "cabin",
    rate: 50,
    highIncrement: 15,
    maxNights: 10,
    maxGuests: 6,
    discounted: (r) => r.loyaltyYears >= 3 || r.coupon === VIP,
    flexible: (r) => r.coupon === VIP || r.loyaltyYears >= 3,
    extraFee: () => 0,
  },
  villa: {
    label: "villa",
    rate: 300,
    highIncrement: 120,
    maxNights: 28,
    maxGuests: 8,
    minStay: 3,
    discounted: (r) => r.loyaltyYears > 2 || r.coupon === VIP,
    flexible: (r) => r.coupon === VIP || r.loyaltyYears >= 3,
    extraFee: () => 500,
  },
};

const isIntegerInRange = (value: unknown, min: number, max: number) =>
  Number.isInteger(value) && (value as number) >= min && (value as number) <= max;

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }

  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const booking: BookingRequest = {
    loyaltyYears: req.loyaltyYears as number,
    nights: req.nights as number,
    guests: req.guests as number,
    season: req.season as "low" | "high",
    coupon: req.coupon as string,
  };

  if (!isIntegerInRange(booking.nights, 1, config.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  if (config.minStay && booking.nights < config.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!isIntegerInRange(booking.guests, 1, config.maxGuests)) {
    return { ok: false, error: "bad guests" };
  }
  if (booking.season !== "low" && booking.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const seasonIncrement = booking.season === "high" ? config.highIncrement : 0;
  let total = (config.rate + seasonIncrement) * booking.nights;
  if (config.discounted(booking)) {
    total -= Math.floor(total / 10);
  }
  total += config.extraFee(booking.guests);

  const policy = config.flexible(booking) ? "flex" : "strict";
  const line = `${config.label}:${booking.nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa" | "cabin";

interface CategoryRule {
  linePrefix: string;
  base: number;
  surcharge: number;
  minNights: number;
  maxNights: number;
  maxGuests: number;
  flatFee: number;
  extra?: (nights: number, guests: number) => number;
}

const CATEGORY_RULES: Record<Category, CategoryRule> = {
  standard: {
    linePrefix: "standard",
    base: 80,
    surcharge: 30,
    minNights: 1,
    maxNights: 14,
    maxGuests: 2,
    flatFee: 0,
  },
  suite: {
    linePrefix: "suite",
    base: 150,
    surcharge: 60,
    minNights: 1,
    maxNights: 21,
    maxGuests: 4,
    flatFee: 0,
    extra: (_nights, guests) => (guests > 2 ? 25 : 0),
  },
  villa: {
    linePrefix: "villa",
    base: 300,
    surcharge: 120,
    minNights: 3,
    maxNights: 28,
    maxGuests: 8,
    flatFee: 500,
  },
  cabin: {
    linePrefix: "cabin",
    base: 50,
    surcharge: 15,
    minNights: 1,
    maxNights: 10,
    maxGuests: 6,
    flatFee: 0,
  },
};

function badNights(req: Record<string, unknown>, rule: CategoryRule): string | undefined {
  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > rule.maxNights) {
    return "bad nights";
  }
  if (rule.minNights > 1 && nights < rule.minNights) {
    return "villa minimum stay";
  }
  return undefined;
}

function badOccupancy(req: Record<string, unknown>, rule: CategoryRule): string | undefined {
  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > rule.maxGuests) {
    return "bad guests";
  }
  if (req.season !== "low" && req.season !== "high") {
    return "bad season";
  }
  return undefined;
}

function validate(req: Record<string, unknown>, rule: CategoryRule): string | undefined {
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return "bad loyalty";
  }
  const nights = badNights(req, rule);
  if (nights) {
    return nights;
  }
  return badOccupancy(req, rule);
}

function price(rule: CategoryRule, req: Record<string, unknown>): Omit<QuoteResult, "ok"> {
  const nights = req.nights as number;
  const guests = req.guests as number;
  const perks = (req.loyaltyYears as number) >= 3 || req.coupon === "VIP";
  let total = (rule.base + (req.season === "high" ? rule.surcharge : 0)) * nights;
  if (perks) {
    total -= Math.floor(total / 10);
  }
  total += (rule.extra ? rule.extra(nights, guests) : 0) + rule.flatFee;
  const policy = perks ? "flex" : "strict";
  const line = `${rule.linePrefix}:${nights}n:${total}:${policy}`;
  return { total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  const rule = CATEGORY_RULES[req.category as Category];
  if (!rule) {
    return { ok: false, error: "unknown category" };
  }
  const invalid = validate(req, rule);
  if (invalid) {
    return { ok: false, error: invalid };
  }
  return { ok: true, ...price(rule, req) };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  baseRate: number;
  highSurcharge: number;
  maxNights: number;
  maxGuests: number;
  minStay?: { nights: number; error: string };
  guestSurcharge?: { above: number; amount: number };
  flatSurcharge?: number;
}

interface Parsed {
  category: string;
  config: CategoryConfig;
  nights: number;
  guests: number;
  high: boolean;
  preferred: boolean;
}

type Validation = { parsed: Parsed } | { error: string };

const PREFERRED_LOYALTY_YEARS = 3;
const SEASONS = new Set(["low", "high"]);

const CONFIG: Record<string, CategoryConfig> = {
  cabin: { baseRate: 50, highSurcharge: 15, maxNights: 10, maxGuests: 6 },
  standard: { baseRate: 80, highSurcharge: 30, maxNights: 14, maxGuests: 2 },
  suite: {
    baseRate: 150,
    highSurcharge: 60,
    maxNights: 21,
    maxGuests: 4,
    guestSurcharge: { above: 2, amount: 25 },
  },
  villa: {
    baseRate: 300,
    highSurcharge: 120,
    maxNights: 28,
    maxGuests: 8,
    minStay: { nights: 3, error: "villa minimum stay" },
    flatSurcharge: 500,
  },
};

function isIntegerBetween(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

function validate(raw: unknown): Validation {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!isIntegerBetween(req.loyaltyYears, 0, Number.MAX_SAFE_INTEGER)) {
    return { error: "bad loyalty" };
  }
  const config = CONFIG[req.category as string];
  if (config === undefined) {
    return { error: "unknown category" };
  }
  if (!isIntegerBetween(req.nights, 1, config.maxNights)) {
    return { error: "bad nights" };
  }
  const nights = req.nights as number;
  if (config.minStay !== undefined && nights < config.minStay.nights) {
    return { error: config.minStay.error };
  }
  if (!isIntegerBetween(req.guests, 1, config.maxGuests)) {
    return { error: "bad guests" };
  }
  if (!SEASONS.has(req.season as string)) {
    return { error: "bad season" };
  }
  return {
    parsed: {
      category: req.category as string,
      config,
      nights,
      guests: req.guests as number,
      high: req.season === "high",
      preferred: req.coupon === "VIP" || (req.loyaltyYears as number) >= PREFERRED_LOYALTY_YEARS,
    },
  };
}

function computeTotal(p: Parsed): number {
  const rate = p.config.baseRate + (p.high ? p.config.highSurcharge : 0);
  let total = rate * p.nights;
  if (p.preferred) {
    total -= Math.floor(total / 10);
  }
  const guestSurcharge = p.config.guestSurcharge;
  if (guestSurcharge !== undefined && p.guests > guestSurcharge.above) {
    total += guestSurcharge.amount;
  }
  const flatSurcharge = p.config.flatSurcharge;
  if (flatSurcharge !== undefined) {
    total += flatSurcharge;
  }
  return total;
}

export function quoteBooking(raw: unknown): QuoteResult {
  const validation = validate(raw);
  if ("error" in validation) {
    return { ok: false, error: validation.error };
  }
  const p = validation.parsed;
  const total = computeTotal(p);
  const policy = p.preferred ? "flex" : "strict";
  const line = `${p.category}:${p.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  name: string;
  maxNights: number;
  minNights: number;
  maxGuests: number;
  baseRate: number;
  highSurcharge: number;
  extraGuestSurcharge: number;
  fixedSurcharge: number;
  minStayNights: number;
}

const CATEGORIES: Record<string, CategorySpec> = {
  standard: {
    name: "standard",
    maxNights: 14,
    minNights: 1,
    maxGuests: 2,
    baseRate: 80,
    highSurcharge: 30,
    extraGuestSurcharge: 0,
    fixedSurcharge: 0,
    minStayNights: 1,
  },
  suite: {
    name: "suite",
    maxNights: 21,
    minNights: 1,
    maxGuests: 4,
    baseRate: 150,
    highSurcharge: 60,
    extraGuestSurcharge: 25,
    fixedSurcharge: 0,
    minStayNights: 1,
  },
  villa: {
    name: "villa",
    maxNights: 28,
    minNights: 1,
    maxGuests: 8,
    baseRate: 300,
    highSurcharge: 120,
    extraGuestSurcharge: 0,
    fixedSurcharge: 500,
    minStayNights: 3,
  },
  cabin: {
    name: "cabin",
    maxNights: 10,
    minNights: 1,
    maxGuests: 6,
    baseRate: 50,
    highSurcharge: 15,
    extraGuestSurcharge: 0,
    fixedSurcharge: 0,
    minStayNights: 1,
  },
};

function isBadInteger(value: unknown, min: number, max: number): boolean {
  return !Number.isInteger(value) || (value as number) < min || (value as number) > max;
}

function parseRequest(raw: unknown): Record<string, unknown> | null {
  if (typeof raw !== "object" || raw === null) {
    return null;
  }
  return raw as Record<string, unknown>;
}

function resolveCategory(req: Record<string, unknown>): { spec?: CategorySpec; error?: string } {
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { error: "bad loyalty" };
  }
  const spec = CATEGORIES[req.category as string];
  if (!spec) {
    return { error: "unknown category" };
  }
  return { spec };
}

function validateInputs(req: Record<string, unknown>, spec: CategorySpec): string | null {
  if (isBadInteger(req.nights, spec.minNights, spec.maxNights)) {
    return "bad nights";
  }
  if ((req.nights as number) < spec.minStayNights) {
    return "villa minimum stay";
  }
  if (isBadInteger(req.guests, 1, spec.maxGuests)) {
    return "bad guests";
  }
  if (req.season !== "low" && req.season !== "high") {
    return "bad season";
  }
  return null;
}

function buildResult(req: Record<string, unknown>, spec: CategorySpec): QuoteResult {
  const nights = req.nights as number;
  const guests = req.guests as number;
  const loyalty = req.loyaltyYears as number;
  const isVip = req.coupon === "VIP";
  const high = req.season === "high";

  let total = nights * spec.baseRate;
  if (high) {
    total += nights * spec.highSurcharge;
  }

  const discounted = isVip || loyalty >= 3;
  if (discounted) {
    total -= Math.floor(total / 10);
  }

  if (guests > 2) {
    total += spec.extraGuestSurcharge;
  }
  total += spec.fixedSurcharge;

  const policy = discounted ? "flex" : "strict";
  const line = `${spec.name}:${String(nights)}n:${String(total)}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const req = parseRequest(raw);
  if (!req) {
    return { ok: false, error: "malformed request" };
  }
  const resolved = resolveCategory(req);
  if (resolved.error) {
    return { ok: false, error: resolved.error };
  }
  const validationError = validateInputs(req, resolved.spec!);
  if (validationError) {
    return { ok: false, error: validationError };
  }
  return buildResult(req, resolved.spec!);
}

