export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
  tag: string | null;
}

const ALIASES: Readonly<Record<string, string>> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const SUPPORTED_FORMATS: ReadonlySet<string> = new Set(["json", "yaml", "text"]);
const SUPPORTED_LOG_LEVELS: ReadonlySet<string> = new Set(["debug", "info", "warn", "error"]);

type FlagSetter = (config: FlagConfig, value: string | undefined) => void;

interface FlagSpec {
  readonly set: FlagSetter;
  readonly takesValue: boolean;
}

function path(name: string, apply: (config: FlagConfig, value: string) => void): FlagSpec {
  return {
    set: (c, v) => {
      if (v === undefined) {
        throw new Error(`--${name} requires a path`);
      }
      apply(c, v);
    },
    takesValue: true,
  };
}

function integer(name: string, apply: (config: FlagConfig, value: number) => void): FlagSpec {
  return {
    set: (c, raw) => {
      const value = Number(raw);
      if (!Number.isInteger(value)) {
        throw new Error(`--${name} must be an integer`);
      }
      apply(c, value);
    },
    takesValue: true,
  };
}

const FLAGS: Readonly<Record<string, FlagSpec>> = {
  "--verbose": { set: (c) => void (c.verbose = true), takesValue: false },
  "--quiet": { set: (c) => void (c.quiet = true), takesValue: false },
  "--dry-run": { set: (c) => void (c.dryRun = true), takesValue: false },
  "--force": { set: (c) => void (c.force = true), takesValue: false },
  "--no-color": { set: (c) => void (c.color = false), takesValue: false },
  "--strict": { set: (c) => void (c.strict = true), takesValue: false },
  "--output": path("output", (c, v) => void (c.outputPath = v)),
  "--config": path("config", (c, v) => void (c.configPath = v)),
  "--format": {
    set: (c, v) => {
      if (v === undefined || !SUPPORTED_FORMATS.has(v)) {
        throw new Error(`unsupported format: ${String(v)}`);
      }
      c.format = v;
    },
    takesValue: true,
  },
  "--log-level": {
    set: (c, v) => {
      if (v === undefined || !SUPPORTED_LOG_LEVELS.has(v)) {
        throw new Error(`unsupported log level: ${String(v)}`);
      }
      c.logLevel = v;
    },
    takesValue: true,
  },
  "--retries": integer("retries", (c, value) => void (c.maxRetries = value)),
  "--timeout": integer("timeout", (c, value) => void (c.timeoutMs = value)),
  "--parallel": integer("parallel", (c, value) => void (c.parallelism = value)),
  "--tag": {
    set: (c, v) => {
      if (v === undefined) {
        throw new Error(`--tag requires a value`);
      }
      c.tag = v;
    },
    takesValue: true,
  },
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
    tag: null,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const spec = FLAGS[arg];

    if (spec === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }

    const value = spec.takesValue ? argv[++i] : undefined;
    spec.set(config, value);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
  tag: string | null;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function requireValue(argv: string[], index: number, option: string): string {
  const value = argv[index];
  if (value === undefined) {
    throw new Error(`${option} requires a path`);
  }
  return value;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
    tag: null,
  };
}

type Handler = (config: FlagConfig, argv: string[], index: number) => number;

function booleanHandler(key: keyof FlagConfig, inverted = false): Handler {
  return (config) => {
    config[key] = !inverted;
    return 0;
  };
}

function enumHandler(key: keyof FlagConfig, values: readonly string[], label: string): Handler {
  return (config, argv, index) => {
    const value = argv[index + 1];
    if (value === undefined || !values.includes(value)) {
      throw new Error(`unsupported ${label}: ${String(value)}`);
    }
    config[key] = value;
    return 1;
  };
}

function numericHandler(key: keyof FlagConfig, option: string): Handler {
  return (config, argv, index) => {
    const value = Number(argv[index + 1]);
    if (!Number.isInteger(value)) {
      throw new Error(`${option} must be an integer`);
    }
    config[key] = value;
    return 1;
  };
}

function stringHandler(key: keyof FlagConfig, option: string): Handler {
  return (config, argv, index) => {
    config[key] = requireValue(argv, index + 1, option);
    return 1;
  };
}

const FORMAT_VALUES = ["json", "yaml", "text"] as const;
const LOG_LEVEL_VALUES = ["debug", "info", "warn", "error"] as const;

const HANDLERS: Record<string, Handler> = {
  "--verbose": booleanHandler("verbose"),
  "--quiet": booleanHandler("quiet"),
  "--dry-run": booleanHandler("dryRun"),
  "--force": booleanHandler("force"),
  "--no-color": booleanHandler("color", true),
  "--strict": booleanHandler("strict"),
  "--output": stringHandler("outputPath", "--output"),
  "--config": stringHandler("configPath", "--config"),
  "--tag": stringHandler("tag", "--tag"),
  "--format": enumHandler("format", FORMAT_VALUES, "format"),
  "--log-level": enumHandler("logLevel", LOG_LEVEL_VALUES, "log level"),
  "--retries": numericHandler("maxRetries", "--retries"),
  "--timeout": numericHandler("timeoutMs", "--timeout"),
  "--parallel": numericHandler("parallelism", "--parallel"),
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const handler = HANDLERS[arg];
    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }
    i += handler(config, argv, i);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
  tag: string | null;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
    tag: null,
  };
}

type BooleanFlag = (config: FlagConfig) => void;
const BOOLEAN_FLAGS: Record<string, BooleanFlag> = {
  "--verbose": (config) => (config.verbose = true),
  "--quiet": (config) => (config.quiet = true),
  "--dry-run": (config) => (config.dryRun = true),
  "--force": (config) => (config.force = true),
  "--no-color": (config) => (config.color = false),
  "--strict": (config) => (config.strict = true),
};

type ValueFlag = (config: FlagConfig, value: string | undefined) => void;
const VALUE_FLAGS: Record<string, ValueFlag> = {
  "--output": (config, value) => {
    if (value === undefined) {
      throw new Error("--output requires a path");
    }
    config.outputPath = value;
  },
  "--config": (config, value) => {
    if (value === undefined) {
      throw new Error("--config requires a path");
    }
    config.configPath = value;
  },
  "--format": (config, value) => {
    if (value === undefined || !["json", "yaml", "text"].includes(value)) {
      throw new Error(`unsupported format: ${String(value)}`);
    }
    config.format = value;
  },
  "--log-level": (config, value) => {
    if (value === undefined || !["debug", "info", "warn", "error"].includes(value)) {
      throw new Error(`unsupported log level: ${String(value)}`);
    }
    config.logLevel = value;
  },
  "--retries": (config, value) => {
    const parsed = Number(value);
    if (!Number.isInteger(parsed)) {
      throw new Error("--retries must be an integer");
    }
    config.maxRetries = parsed;
  },
  "--timeout": (config, value) => {
    const parsed = Number(value);
    if (!Number.isInteger(parsed)) {
      throw new Error("--timeout must be an integer");
    }
    config.timeoutMs = parsed;
  },
  "--tag": (config, value) => {
    if (value === undefined) {
      throw new Error("--tag requires a value");
    }
    config.tag = value;
  },
  "--parallel": (config, value) => {
    const parsed = Number(value);
    if (!Number.isInteger(parsed)) {
      throw new Error("--parallel must be an integer");
    }
    config.parallelism = parsed;
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const boolean = BOOLEAN_FLAGS[arg];
    if (boolean) {
      boolean(config);
      continue;
    }

    const valueFlag = VALUE_FLAGS[arg];
    if (valueFlag) {
      valueFlag(config, argv[++i]);
      continue;
    }

    throw new Error(`unknown flag: ${arg}`);
  }

  return config;
}

