export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa" | "cabin";

interface CategoryConfig {
  maxNights: number;
  basePerNight: number;
  highSurcharge: number;
  maxGuests: number;
  minStay: number;
  guestExcessFee: number;
  flatFee: number;
}

const CATEGORY_CONFIG: Record<Category, CategoryConfig> = {
  standard: { maxNights: 14, basePerNight: 80, highSurcharge: 30, maxGuests: 2, minStay: 0, guestExcessFee: 0, flatFee: 0 },
  suite: { maxNights: 21, basePerNight: 150, highSurcharge: 60, maxGuests: 4, minStay: 0, guestExcessFee: 25, flatFee: 0 },
  villa: { maxNights: 28, basePerNight: 300, highSurcharge: 120, maxGuests: 8, minStay: 3, guestExcessFee: 0, flatFee: 500 },
  cabin: { maxNights: 10, basePerNight: 50, highSurcharge: 15, maxGuests: 6, minStay: 0, guestExcessFee: 0, flatFee: 0 },
};

function intInRange(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = req.loyaltyYears as number;
  const nights = req.nights as number;
  const guests = req.guests as number;
  const coupon = typeof req.coupon === "string" ? (req.coupon as string) : undefined;

  if (!intInRange(loyaltyYears, 0, Number.MAX_SAFE_INTEGER)) {
    return { ok: false, error: "bad loyalty" };
  }
  const category = CATEGORY_CONFIG[req.category as Category];
  if (!category) {
    return { ok: false, error: "unknown category" };
  }
  if (!intInRange(nights, 1, category.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  if (category.minStay > 0 && nights < category.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!intInRange(guests, 1, category.maxGuests)) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = category.basePerNight * nights;
  if (req.season === "high") {
    total += category.highSurcharge * nights;
  }
  const vip = coupon === "VIP";
  const discounted = vip || loyaltyYears >= 3;
  if (discounted) {
    total -= Math.floor(total / 10);
  }
  if (category.guestExcessFee > 0 && guests > 2) {
    total += category.guestExcessFee;
  }
  total += category.flatFee;

  const policy: "flex" | "strict" = discounted ? "flex" : "strict";
  const line = `${req.category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

