  color: boolean;
  strict: boolean;
  tag: string | null;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const FORMATS = ["json", "yaml", "text"] as const;
const LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
    tag: null,
  };
}

function requireValue(argv: string[], index: number, flag: string): string {
  const value = argv[index];
  if (value === undefined) {
    throw new Error(`${flag} requires a path`);
  }
  return value;
}

function requireInteger(argv: string[], index: number, flag: string): number {
  const value = Number(argv[index]);
  if (!Number.isInteger(value)) {
    throw new Error(`${flag} must be an integer`);
  }
  return value;
}

type Handler = (config: FlagConfig, argv: string[], index: number) => number;

const FLAG_HANDLERS: Record<string, Handler> = {
  "--verbose": (c) => {
    c.verbose = true;
    return 0;
  },
  "--quiet": (c) => {
    c.quiet = true;
    return 0;
  },
  "--dry-run": (c) => {
    c.dryRun = true;
    return 0;
  },
  "--force": (c) => {
    c.force = true;
    return 0;
  },
  "--no-color": (c) => {
    c.color = false;
    return 0;
  },
  "--strict": (c) => {
    c.strict = true;
    return 0;
  },
  "--output": (c, argv, i) => {
    c.outputPath = requireValue(argv, i + 1, "--output");
    return 1;
  },
  "--config": (c, argv, i) => {
    c.configPath = requireValue(argv, i + 1, "--config");
    return 1;
  },
  "--tag": (c, argv, i) => {
    c.tag = requireValue(argv, i + 1, "--tag");
    return 1;
  },
  "--format": (c, argv, i) => {
    const value = requireValue(argv, i + 1, "--format");
    if (!(FORMATS as readonly string[]).includes(value)) {
      throw new Error(`unsupported format: ${String(value)}`);
    }
    c.format = value;
    return 1;
  },
  "--log-level": (c, argv, i) => {
    const value = requireValue(argv, i + 1, "--log-level");
    if (!(LOG_LEVELS as readonly string[]).includes(value)) {
      throw new Error(`unsupported log level: ${String(value)}`);
    }
    c.logLevel = value;
    return 1;
  },
  "--retries": (c, argv, i) => {
