    return 1;
  },
  "--timeout": (c, argv, i) => {
    c.timeoutMs = requireInteger(argv, i + 1, "--timeout");
    return 1;
  },
  "--parallel": (c, argv, i) => {
    c.parallelism = requireInteger(argv, i + 1, "--parallel");
    return 1;
  },
