interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  originalWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function isNonEmptyString(x: unknown): boolean {
  return typeof x === "string" && x.length > 0;
}

function isPositiveInt(x: unknown): boolean {
  return Number.isInteger(x) && (x as number) >= 1;
}

function isNonNegativeInt(x: unknown): boolean {
  return Number.isInteger(x) && (x as number) >= 0;
}

function level(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function serveQueue(state: State) {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHand = level(state.stock, want.item);
    if (onHand >= want.qty) {
      state.stock[want.item] = onHand - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReservation(state: State, id: string, status: string) {
  const holding = state.reserved[id];
  state.stock[holding.item] = level(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  serveQueue(state);
}

function rejectUnrecognized(state: State) {
  state.rejected = state.rejected + 1;
}

type Handler = (state: State, event: Record<string, unknown>, index: number) => string | null;

function handleOrder(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  const item = event.item;
  const qty = event.qty;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (state.orders[id as string] !== undefined) return "event " + index + ": duplicate order";
  if (!isNonEmptyString(item)) return "event " + index + ": bad item";
  if (!isPositiveInt(qty)) return "event " + index + ": bad qty";
  state.originalWants[id as string] = { item: item as string, qty: qty as number };
  if (level(state.stock, item as string) >= (qty as number)) {
    state.stock[item as string] = level(state.stock, item as string) - (qty as number);
    state.reserved[id as string] = { item: item as string, qty: qty as number };
    state.orders[id as string] = "reserved";
  } else {
    state.queue.push(id as string);
    state.pendingWants[id as string] = { item: item as string, qty: qty as number };
    state.orders[id as string] = "backordered";
  }
  return null;
}

function handleCancel(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (state.reserved[id as string] !== undefined) {
    releaseReservation(state, id as string, "cancelled");
  } else if (state.orders[id as string] === "backordered") {
    state.queue.splice(state.queue.indexOf(id as string), 1);
    delete state.pendingWants[id as string];
    state.orders[id as string] = "cancelled";
  } else {
    rejectUnrecognized(state);
  }
  return null;
}

function handleShip(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  const qty = event.qty;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (qty !== undefined && !isPositiveInt(qty)) return "event " + index + ": bad qty";
  const res = state.reserved[id as string];
  if (res === undefined) {
    rejectUnrecognized(state);
    return null;
  }
  const shipped = qty === undefined || (qty as number) === res.qty;
  if (shipped) {
    delete state.reserved[id as string];
    state.orders[id as string] = "shipped";
    return null;
  }
  if ((qty as number) < res.qty) {
    res.qty = res.qty - (qty as number);
    state.orders[id as string] = "partial";
    return null;
  }
  rejectUnrecognized(state);
  return null;
}

function handleRestock(state: State, event: Record<string, unknown>, index: number): string | null {
  const item = event.item;
  const qty = event.qty;
  if (!isNonEmptyString(item)) return "event " + index + ": bad item";
  if (!isPositiveInt(qty)) return "event " + index + ": bad qty";
  state.stock[item as string] = level(state.stock, item as string) + (qty as number);
  serveQueue(state);
  return null;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (state.reserved[id as string] !== undefined) {
    releaseReservation(state, id as string, "expired");
  } else {
    rejectUnrecognized(state);
  }
  return null;
}

function handleReturn(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (state.orders[id as string] === "shipped") {
    const holding = state.originalWants[id as string];
    state.stock[holding.item] = level(state.stock, holding.item) + holding.qty;
    state.orders[id as string] = "returned";
    serveQueue(state);
  } else {
    rejectUnrecognized(state);
  }
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

function processOne(state: State, event: unknown, index: number): string | null {
  if (typeof event !== "object" || event === null) {
    return "event " + index + ": malformed";
  }
  const e = event as Record<string, unknown>;
  const handler = HANDLERS[e.type as string];
  if (handler === undefined) {
    return "event " + index + ": bad type";
  }
  return handler(state, e, index);
}

interface ParsedInput {
  ok: boolean;
  error?: string;
  stock?: unknown;
  events?: unknown[];
}

function parseInput(raw: unknown): ParsedInput {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  return { ok: true, stock: input.stock, events: input.events };
}

function parseStock(raw: unknown): { ok: boolean; error?: string; stock?: Record<string, number> } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "bad stock" };
  }
  const rawStock = raw as Record<string, unknown>;
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    if (!isNonNegativeInt(rawStock[item])) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { ok: true, stock };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const input = parseInput(raw);
  if (!input.ok) {
    return { ok: false, error: input.error };
  }
  const parsedStock = parseStock(input.stock);
  if (!parsedStock.ok || parsedStock.stock === undefined) {
    return { ok: false, error: parsedStock.error };
  }
  const state: State = {
    stock: parsedStock.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    originalWants: {},
    queue: [],
    rejected: 0,
  };
  const events = input.events as unknown[];
  for (let index = 0; index < events.length; index++) {
    const err = processOne(state, events[index], index);
    if (err !== null) {
      return { ok: false, error: err };
    }
  }
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  shipped: Record<string, Want>;
  queue: string[];
  rejected: number;
}

const onHand = (stock: Record<string, number>, item: string): number =>
  stock[item] === undefined ? 0 : stock[item];

const fulfillQueue = (state: State): void => {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    if (onHand(state.stock, want.item) >= want.qty) {
      state.stock[want.item] = onHand(state.stock, want.item) - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
};

const releaseReservation = (state: State, id: string, status: string): void => {
  const holding = state.reserved[id];
  state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  fulfillQueue(state);
};

type Field = "id" | "item" | "qty";

interface Rule {
  field: Field;
  optional?: boolean;
}

const ID_RULE: Rule = { field: "id" };
const ITEM_RULE: Rule = { field: "item" };
const QTY_RULE: Rule = { field: "qty" };
const OPTIONAL_QTY_RULE: Rule = { field: "qty", optional: true };

const EVENT_RULES: Record<string, Rule[]> = {
  order: [ID_RULE, ITEM_RULE, QTY_RULE],
  cancel: [ID_RULE],
  ship: [ID_RULE, OPTIONAL_QTY_RULE],
  restock: [ITEM_RULE, QTY_RULE],
  expire: [ID_RULE],
  return: [ID_RULE],
};

const QTY_OK = (v: unknown): boolean => Number.isInteger(v) && (v as number) >= 1;
const TEXT_OK = (v: unknown): boolean => typeof v === "string" && (v as string).length > 0;

function validateEvent(type: string, event: Record<string, unknown>, index: number): string | null {
  for (const rule of EVENT_RULES[type]) {
    const value = event[rule.field];
    const valid = rule.optional && value === undefined ? true : rule.field === "qty" ? QTY_OK(value) : TEXT_OK(value);
    if (!valid) {
      const label = rule.field === "item" ? "item" : rule.field === "qty" ? "qty" : "id";
      return "event " + index + ": bad " + label;
    }
  }
  return null;
}

function eventOrder(state: State, event: Record<string, unknown>): string | null {
  if (state.orders[event.id] !== undefined) {
    return "duplicate order";
  }
  const qty = event.qty as number;
  if (onHand(state.stock, event.item) >= qty) {
    state.stock[event.item] = onHand(state.stock, event.item) - qty;
    state.reserved[event.id] = { item: event.item, qty };
    state.orders[event.id] = "reserved";
  } else {
    state.queue.push(event.id);
    state.pendingWants[event.id] = { item: event.item, qty };
    state.orders[event.id] = "backordered";
  }
  return null;
}

function eventCancel(state: State, event: Record<string, unknown>): string | null {
  if (state.reserved[event.id] !== undefined) {
    releaseReservation(state, event.id, "cancelled");
  } else if (state.orders[event.id] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id), 1);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function eventShip(state: State, event: Record<string, unknown>): string | null {
  const holding = state.reserved[event.id];
  const qty = event.qty as number;
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || qty === holding.qty) {
    state.shipped[event.id] = { item: holding.item, qty: holding.qty };
    delete state.reserved[event.id];
    state.orders[event.id] = "shipped";
  } else if (qty < holding.qty) {
    holding.qty = holding.qty - qty;
    state.orders[event.id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function eventRestock(state: State, event: Record<string, unknown>): string | null {
  state.stock[event.item] = onHand(state.stock, event.item) + (event.qty as number);
  fulfillQueue(state);
  return null;
}

function eventExpire(state: State, event: Record<string, unknown>): string | null {
  if (state.reserved[event.id] !== undefined) {
    releaseReservation(state, event.id, "expired");
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function eventReturn(state: State, event: Record<string, unknown>): string | null {
  if (state.orders[event.id] === "shipped") {
    const shipped = state.shipped[event.id];
    state.stock[shipped.item] = onHand(state.stock, shipped.item) + shipped.qty;
    delete state.shipped[event.id];
    state.orders[event.id] = "returned";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

const EVENT_HANDLERS: Record<string, (state: State, event: Record<string, unknown>) => string | null> = {
  order: eventOrder,
  cancel: eventCancel,
  ship: eventShip,
  restock: eventRestock,
  expire: eventExpire,
  return: eventReturn,
};

function parseStock(raw: unknown): { stock: Record<string, number>; error?: string } {
  const rawStock = (raw as Record<string, unknown>).stock;
  if (typeof rawStock !== "object" || rawStock === null) {
    return { stock: {}, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    const value = (rawStock as Record<string, unknown>)[item];
    if (!Number.isInteger(value) || (value as number) < 0) {
      return { stock: {}, error: "bad stock" };
    }
    stock[item] = value as number;
  }
  return { stock };
}

function runEvents(input: Record<string, unknown>, state: State): string | null {
  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return "event " + index + ": malformed";
    }
    const type = event.type as string;
    const handler = EVENT_HANDLERS[type];
    if (handler === undefined) {
      return "event " + index + ": bad type";
    }
    const error = validateEvent(type, event, index);
    if (error !== null) {
      return error;
    }
    const handlerError = handler(state, event);
    if (handlerError !== null) {
      return "event " + index + ": " + handlerError;
    }
  }
  return null;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const parsed = parseStock(raw);
  if (parsed.error !== undefined) {
    return { ok: false, error: parsed.error };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock: parsed.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    shipped: {},
    queue: [],
    rejected: 0,
  };

  const error = runEvents(input, state);
  if (error !== null) {
    return { ok: false, error };
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"] as const;

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    const status = orders[id];
    if (status in counts) {
      counts[status] = counts[status] + 1;
    }
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

