    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: OrdersMap = {};
  const reserved: Record<string, Want> = {};
  const shipped: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return eventError(index, "malformed");
    }

    if (event.type === "order") {
      if (!isNonEmptyString(event.id)) {
        return eventError(index, "bad id");
      }
      if (orders[event.id] !== undefined) {
        return eventError(index, "duplicate order");
      }
      if (!isNonEmptyString(event.item)) {
        return eventError(index, "bad item");
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return eventError(index, "bad qty");
      }
      const available = stockOf(stock, event.item);
      if (available >= (event.qty as number)) {
        stock[event.item] = available - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (!isNonEmptyString(event.id)) {
        return eventError(index, "bad id");
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        restockHolding(event.id, holding, stock);
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        fulfillQueue(queue, pendingWants, stock, reserved, orders);
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (!isNonEmptyString(event.id)) {
        return eventError(index, "bad id");
      }
      if (event.qty !== undefined && !isPositiveInt(event.qty)) {
        return eventError(index, "bad qty");
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        shipped[event.id] = { item: reserved[event.id].item, qty: reserved[event.id].qty };
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (!isNonEmptyString(event.item)) {
        return eventError(index, "bad item");
      }
      if (!isPositiveInt(event.qty)) {
        return eventError(index, "bad qty");
      }
      stock[event.item] = stockOf(stock, event.item) + (event.qty as number);
      fulfillQueue(queue, pendingWants, stock, reserved, orders);
    } else if (event.type === "return") {
      if (!isNonEmptyString(event.id)) {
        return eventError(index, "bad id");
      }
      if (orders[event.id] === "shipped") {
        const holding = shipped[event.id];
        restockHolding(event.id, holding, stock);
        delete shipped[event.id];
        orders[event.id] = "returned";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "expire") {
      if (!isNonEmptyString(event.id)) {
        return eventError(index, "bad id");
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        restockHolding(event.id, holding, stock);
        delete reserved[event.id];
        orders[event.id] = "expired";
        fulfillQueue(queue, pendingWants, stock, reserved, orders);
      } else {
        rejected = rejected + 1;
      }
    } else {
      return eventError(index, "bad type");
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: OrdersMap): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    const status = orders[id];
    if (STATUSES.includes(status)) {
      counts[status] = counts[status] + 1;
    }
  }
  return counts;
}

function buildReport(orders: OrdersMap, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  fullOrder: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Event = Record<string, unknown>;
type Error = string;
type ReadResult<T> = { ok: true; value: T } | { ok: false; error: string };

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function readId(event: Event, index: number): ReadResult<string> {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  return { ok: true, value: event.id };
}

function readItem(event: Event, index: number): ReadResult<string> {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return { ok: false, error: "event " + index + ": bad item" };
  }
  return { ok: true, value: event.item };
}

function readQty(event: Event, index: number): ReadResult<number> {
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  return { ok: true, value: event.qty as number };
}

function drainQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHandQty = onHand(state.stock, want.item);
    if (onHandQty >= want.qty) {
      state.stock[want.item] = onHandQty - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function placeOrder(state: State, event: Event, index: number): Error | void {
  const id = readId(event, index);
  if (!id.ok) return id.error;
  if (state.orders[id.value] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  const item = readItem(event, index);
  if (!item.ok) return item.error;
  const qty = readQty(event, index);
  if (!qty.ok) return qty.error;

  state.fullOrder[id.value] = { item: item.value, qty: qty.value };

  if (onHand(state.stock, item.value) >= qty.value) {
    state.stock[item.value] = onHand(state.stock, item.value) - qty.value;
    state.reserved[id.value] = { item: item.value, qty: qty.value };
    state.orders[id.value] = "reserved";
  } else {
    state.queue.push(id.value);
    state.pendingWants[id.value] = { item: item.value, qty: qty.value };
    state.orders[id.value] = "backordered";
  }
}

function releaseReserved(state: State, id: string, status: string): void {
  const holding = state.reserved[id];
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
    return;
  }
  state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  drainQueue(state);
}

function cancelOrder(state: State, event: Event, index: number): Error | void {
  const id = readId(event, index);
  if (!id.ok) return id.error;

  if (state.orders[id.value] === "backordered") {
    state.queue.splice(state.queue.indexOf(id.value), 1);
    delete state.pendingWants[id.value];
    state.orders[id.value] = "cancelled";
    return;
  }
  releaseReserved(state, id.value, "cancelled");
}

function applyShip(state: State, id: string, shipQty: number): void {
  const holding = state.reserved[id];
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
    return;
  }
  if (shipQty > holding.qty) {
    state.rejected = state.rejected + 1;
    return;
  }
  const remaining = holding.qty - shipQty;
  if (remaining === 0) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
    return;
  }
  state.reserved[id].qty = remaining;
  state.orders[id] = "partial";
}

function shipOrder(state: State, event: Event, index: number): Error | void {
  const id = readId(event, index);
  if (!id.ok) return id.error;
  if (event.qty !== undefined) {
    if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
      return "event " + index + ": bad qty";
    }
  }
  const shipQty = event.qty === undefined ? state.reserved[id.value]?.qty ?? 0 : (event.qty as number);
  applyShip(state, id.value, shipQty);
}

function returnOrder(state: State, event: Event, index: number): Error | void {
  const id = readId(event, index);
  if (!id.ok) return id.error;
  if (state.orders[id.value] !== "shipped") {
    state.rejected = state.rejected + 1;
    return;
  }
  const full = state.fullOrder[id.value];
  state.stock[full.item] = onHand(state.stock, full.item) + full.qty;
  state.orders[id.value] = "returned";
  drainQueue(state);
}

function restock(state: State, event: Event, index: number): Error | void {
  const item = readItem(event, index);
  if (!item.ok) return item.error;
  const qty = readQty(event, index);
  if (!qty.ok) return qty.error;

  state.stock[item.value] = onHand(state.stock, item.value) + qty.value;
  drainQueue(state);
}

function expireOrder(state: State, event: Event, index: number): Error | void {
  const id = readId(event, index);
  if (!id.ok) return id.error;
  releaseReserved(state, id.value, "expired");
}

const HANDLERS: Record<string, (state: State, event: Event, index: number) => Error | void> = {
  order: placeOrder,
  cancel: cancelOrder,
  ship: shipOrder,
  restock: restock,
  expire: expireOrder,
  return: returnOrder,
};

function parseStock(input: Record<string, unknown>): ReadResult<Record<string, number>> {
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const rawStock = input.stock as Record<string, unknown>;
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { ok: true, value: stock };
}

function applyEvents(events: unknown[], state: State): Error | void {
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return "event " + index + ": malformed";
    }
    const handler = HANDLERS[(event as Event).type as string];
    if (handler === undefined) {
      return "event " + index + ": bad type";
    }
    const result = handler(state, event as Event, index);
    if (typeof result === "string") {
      return result;
    }
  }
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stockRes = parseStock(input);
  if (!stockRes.ok) {
    return { ok: false, error: stockRes.error };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock: stockRes.value,
    orders: {},
    reserved: {},
    pendingWants: {},
    fullOrder: {},
    queue: [],
    rejected: 0,
  };

  const error = applyEvents(input.events, state);
  if (typeof error === "string") {
    return { ok: false, error };
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    if (STATUSES.indexOf(orders[id]) < 0) {
      continue;
    }
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Ctx {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
  orderMeta: Record<string, Want>;
}

type Handler = (event: Record<string, unknown>, ctx: Ctx) => string | null;

function stockOf(ctx: Ctx, item: string): number {
  return ctx.stock[item] === undefined ? 0 : ctx.stock[item];
}

function tryFillBacklog(ctx: Ctx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = stockOf(ctx, want.item);
    if (onHand < want.qty) {
      continue;
    }
    ctx.stock[want.item] = onHand - want.qty;
    ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
    ctx.orders[pendingId] = "reserved";
    delete ctx.pendingWants[pendingId];
    ctx.queue.splice(position, 1);
    position = position - 1;
  }
}

function releaseReservation(id: string, ctx: Ctx, outcome: string): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = stockOf(ctx, holding.item) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = outcome;
  tryFillBacklog(ctx);
}

function reserveOrder(ctx: Ctx, id: string, item: string, qty: number): void {
  ctx.stock[item] = stockOf(ctx, item) - qty;
  ctx.reserved[id] = { item, qty };
  ctx.orders[id] = "reserved";
}

function backorderOrder(ctx: Ctx, id: string, item: string, qty: number): void {
  ctx.queue.push(id);
  ctx.pendingWants[id] = { item, qty };
  ctx.orders[id] = "backordered";
}

function handleOrder(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  if (ctx.orders[id] !== undefined) {
    return "duplicate order";
  }
  const qty = event.qty as number;
  ctx.orderMeta[id] = { item: event.item as string, qty };
  if (stockOf(ctx, event.item as string) >= qty) {
    reserveOrder(ctx, id, event.item as string, qty);
  } else {
    backorderOrder(ctx, id, event.item as string, qty);
  }
  return null;
}

function handleCancel(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    releaseReservation(id, ctx, "cancelled");
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleShip(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  const reservation = ctx.reserved[id];
  if (reservation === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (event.qty === undefined || event.qty === reservation.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if ((event.qty as number) < reservation.qty) {
    reservation.qty = reservation.qty - (event.qty as number);
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleRestock(event: Record<string, unknown>, ctx: Ctx): string | null {
  ctx.stock[event.item as string] =
    stockOf(ctx, event.item as string) + (event.qty as number);
  tryFillBacklog(ctx);
  return null;
}

function handleExpire(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    releaseReservation(id, ctx, "expired");
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleReturn(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  if (ctx.orders[id] !== "shipped") {
    ctx.rejected = ctx.rejected + 1;
    return null;
  }
  const meta = ctx.orderMeta[id];
  ctx.stock[meta.item] = stockOf(ctx, meta.item) + meta.qty;
  ctx.orders[id] = "returned";
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

type Validation = { name: string; check: (event: Record<string, unknown>) => boolean };

const validators: Record<string, Validation> = {
  id: {
    name: "id",
    check: (event) => typeof event.id !== "string" || (event.id as string).length === 0,
  },
  item: {
    name: "item",
    check: (event) => typeof event.item !== "string" || (event.item as string).length === 0,
  },
  qty: {
    name: "qty",
    check: (event) => !Number.isInteger(event.qty) || (event.qty as number) < 1,
  },
  optQty: {
    name: "qty",
    check: (event) =>
      event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1),
  },
};

const EVENT_SPEC: Record<string, string[]> = {
  order: ["id", "item", "qty"],
  cancel: ["id"],
  ship: ["id", "optQty"],
  restock: ["item", "qty"],
  expire: ["id"],
  return: ["id"],
};

function validateEvent(event: Record<string, unknown>, spec: string[]): string | null {
  for (const kind of spec) {
    if (validators[kind].check(event)) {
      return "bad " + validators[kind].name;
    }
  }
  return null;
}

function runEvents(
  events: Record<string, unknown>[],
  ctx: Ctx,
): { ok: true } | { ok: false; error: string } {
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const type = event.type as string;
    const handler = HANDLERS[type];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const reason = validateEvent(event, EVENT_SPEC[type]) ?? handler(event, ctx);
    if (reason !== null) {
      return { ok: false, error: "event " + index + ": " + reason };
    }
  }
  return { ok: true };
}

function parseStock(input: Record<string, unknown>): Record<string, number> | null {
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const qty = rawStock[item];
    if (!Number.isInteger(qty) || (qty as number) < 0) {
      return null;
    }
    stock[item] = qty as number;
  }
  return stock;
}

function buildResult(ctx: Ctx): FulfillmentResult {
  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock = parseStock(input);
  if (stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Ctx = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
    orderMeta: {},
  };
  const outcome = runEvents(input.events as Record<string, unknown>[], ctx);
  if (!outcome.ok) {
    return outcome;
  }
  return buildResult(ctx);
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    if (STATUSES.indexOf(orders[id]) !== -1) {
      counts[orders[id]] = counts[orders[id]] + 1;
    }
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

