files.process_events.ts:
interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Line extends Want {}

interface Ctx {
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  lines: Record<string, Line>;
  queue: string[];
  rejected: number;
}

export function processEvents(raw: unknown): FulfillmentResult {
  let stock: Record<string, number>;
  let events: Record<string, unknown>[];
  try {
    stock = parseStock(raw);
    events = parseEvents(raw);
  } catch (err) {
    return { ok: false, error: (err as Error).message };
  }

  const ctx: Ctx = {
    orders: {},
    reserved: {},
    pendingWants: {},
    lines: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const outcome = handler(event, ctx, stock);
    if (!outcome.ok) {
      return { ok: false, error: "event " + index + ": " + outcome.error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

interface Outcome {
  ok: boolean;
  error?: string;
}
type Handler = (event: Record<string, unknown>, ctx: Ctx, stock: Record<string, number>) => Outcome;

function isIntegerGE1(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 1;
}
function isText(value: unknown): boolean {
  return typeof value === "string" && value.length > 0;
}
function ok(): Outcome {
  return { ok: true };
}
function err(error: string): Outcome {
  return { ok: false, error };
}

function handleOrder(event: Record<string, unknown>, ctx: Ctx, stock: Record<string, number>): Outcome {
  if (!isText(event.id)) return err("bad id");
  if (!isText(event.item)) return err("bad item");
  if (!isIntegerGE1(event.qty)) return err("bad qty");
  if (ctx.orders[event.id] !== undefined) return err("duplicate order");

  const qty = event.qty as number;
  ctx.lines[event.id] = { item: event.item, qty };
  placeOrBackorder(stock, ctx, event.id as string, event.item as string, qty);
  return ok();
}

function placeOrBackorder(
  stock: Record<string, number>,
  ctx: Ctx,
  id: string,
  item: string,
  qty: number
): void {
  const available = stock[item] ?? 0;
  if (available >= qty) {
    stock[item] = available - qty;
    ctx.reserved[id] = { item, qty };
    ctx.orders[id] = "reserved";
  } else {
    ctx.queue.push(id);
    ctx.pendingWants[id] = { item, qty };
    ctx.orders[id] = "backordered";
  }
}

function handleCancel(event: Record<string, unknown>, ctx: Ctx, stock: Record<string, number>): Outcome {
  if (!isText(event.id)) return err("bad id");
  if (ctx.reserved[event.id] !== undefined) {
    const holding = ctx.reserved[event.id];
    stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "cancelled";
    satisfyQueue(ctx, stock);
  } else if (ctx.orders[event.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(event.id), 1);
    delete ctx.pendingWants[event.id];
    ctx.orders[event.id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return ok();
}

function handleShip(event: Record<string, unknown>, ctx: Ctx): Outcome {
  if (!isText(event.id)) return err("bad id");
  if (event.qty !== undefined && !isIntegerGE1(event.qty)) return err("bad qty");
  const reserved = ctx.reserved[event.id];
  if (reserved === undefined) {
    ctx.rejected = ctx.rejected + 1;
    return ok();
  }
  if (event.qty === undefined || (event.qty as number) === reserved.qty) {
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "shipped";
  } else if ((event.qty as number) < reserved.qty) {
    reserved.qty = reserved.qty - (event.qty as number);
    ctx.orders[event.id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return ok();
}

function handleRestock(event: Record<string, unknown>, ctx: Ctx, stock: Record<string, number>): Outcome {
  if (!isText(event.item)) return err("bad item");
  if (!isIntegerGE1(event.qty)) return err("bad qty");
  stock[event.item] = (stock[event.item] ?? 0) + (event.qty as number);
  satisfyQueue(ctx, stock);
  return ok();
}

function handleExpire(event: Record<string, unknown>, ctx: Ctx, stock: Record<string, number>): Outcome {
  if (!isText(event.id)) return err("bad id");
  if (ctx.reserved[event.id] !== undefined) {
    const holding = ctx.reserved[event.id];
    stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "expired";
    satisfyQueue(ctx, stock);
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return ok();
}

function handleReturn(event: Record<string, unknown>, ctx: Ctx, stock: Record<string, number>): Outcome {
  if (!isText(event.id)) return err("bad id");
  const state = ctx.orders[event.id];
  if (state !== "shipped" && state !== "partial") {
    ctx.rejected = ctx.rejected + 1;
    return ok();
  }
  if (ctx.reserved[event.id] !== undefined) {
    delete ctx.reserved[event.id];
  }
  const line = ctx.lines[event.id];
  stock[line.item] = (stock[line.item] ?? 0) + line.qty;
  ctx.orders[event.id] = "returned";
  satisfyQueue(ctx, stock);
  return ok();
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

function parseStock(raw: unknown): Record<string, number> {
  if (typeof raw !== "object" || raw === null) {
    throw new Error("malformed input");
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    throw new Error("bad stock");
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      throw new Error("bad stock");
    }
    stock[item] = rawStock[item] as number;
  }
  return stock;
}

function parseEvents(raw: unknown): Record<string, unknown>[] {
  const input = raw as Record<string, unknown>;
  if (!Array.isArray(input.events)) {
    throw new Error("bad events");
  }
  return input.events as Record<string, unknown>[];
}

function satisfyQueue(ctx: Ctx, stock: Record<string, number>): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    const status = orders[id];
    if (counts[status] !== undefined) {
      counts[status] = counts[status] + 1;
    }
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

