interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function addStock(stock: Record<string, number>, item: string, qty: number): void {
  stock[item] = onHand(stock, item) + qty;
}

function takeStock(stock: Record<string, number>, item: string, qty: number): void {
  stock[item] = onHand(stock, item) - qty;
}

const badId = (event: Record<string, unknown>): boolean =>
  typeof event.id !== "string" || event.id.length === 0;
const badItem = (event: Record<string, unknown>): boolean =>
  typeof event.item !== "string" || event.item.length === 0;
const badQty = (value: unknown): boolean =>
  !Number.isInteger(value) || (value as number) < 1;

function fulfillQueue(
  queue: string[],
  pendingWants: Record<string, Want>,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    if (onHand(stock, want.item) >= want.qty) {
      takeStock(stock, want.item, want.qty);
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReservation(
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  queue: string[],
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
  id: string,
  status: string,
): void {
  const holding = reserved[id];
  addStock(stock, holding.item, holding.qty);
  delete reserved[id];
  orders[id] = status;
  fulfillQueue(queue, pendingWants, stock, reserved, orders);
}

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

function parseStock(raw: Record<string, unknown>): Record<string, number> | string {
  if (typeof raw.stock !== "object" || raw.stock === null) {
    return "bad stock";
  }
  const stock: Record<string, number> = {};
  const rawStock = raw.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (badQty(rawStock[item])) {
      return "bad stock";
    }
    stock[item] = rawStock[item] as number;
  }
  return stock;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  const parsedStock = parseStock(input);
  if (typeof parsedStock === "string") {
    return { ok: false, error: parsedStock };
  }
  const stock = parsedStock;

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const shipped: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const kind = event.type;
    if (kind === "order") {
      if (badId(event)) return { ok: false, error: "event " + index + ": bad id" };
      if (badItem(event)) return { ok: false, error: "event " + index + ": bad item" };
      if (badQty(event.qty)) return { ok: false, error: "event " + index + ": bad qty" };
      const id = event.id as string;
      if (orders[id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      const item = event.item as string;
      const qty = event.qty as number;
      if (onHand(stock, item) >= qty) {
        takeStock(stock, item, qty);
        reserved[id] = { item, qty };
        orders[id] = "reserved";
      } else {
        queue.push(id);
        pendingWants[id] = { item, qty };
        orders[id] = "backordered";
      }
    } else if (kind === "cancel") {
      if (badId(event)) return { ok: false, error: "event " + index + ": bad id" };
      const id = event.id as string;
      if (reserved[id] !== undefined) {
        releaseReservation(stock, reserved, queue, pendingWants, orders, id, "cancelled");
      } else if (orders[id] === "backordered") {
        queue.splice(queue.indexOf(id), 1);
        delete pendingWants[id];
        orders[id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (kind === "ship") {
      if (badId(event)) return { ok: false, error: "event " + index + ": bad id" };
      if (event.qty !== undefined && badQty(event.qty)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const id = event.id as string;
      const qty = (event.qty as number) || 0;
      const holding = reserved[id];
      if (holding === undefined) {
        rejected = rejected + 1;
      } else if (qty === 0 || qty === holding.qty) {
        delete reserved[id];
        shipped[id] = { item: holding.item, qty: holding.qty };
        orders[id] = "shipped";
      } else if (qty < holding.qty) {
        holding.qty = holding.qty - qty;
        orders[id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (kind === "restock") {
      if (badItem(event)) return { ok: false, error: "event " + index + ": bad item" };
      if (badQty(event.qty)) return { ok: false, error: "event " + index + ": bad qty" };
      addStock(stock, event.item as string, event.qty as number);
      fulfillQueue(queue, pendingWants, stock, reserved, orders);
    } else if (kind === "expire") {
      if (badId(event)) return { ok: false, error: "event " + index + ": bad id" };
      const id = event.id as string;
      if (reserved[id] !== undefined) {
        releaseReservation(stock, reserved, queue, pendingWants, orders, id, "expired");
      } else {
        rejected = rejected + 1;
      }
    } else if (kind === "return") {
      if (badId(event)) return { ok: false, error: "event " + index + ": bad id" };
      const id = event.id as string;
      const shippedOrder = shipped[id];
      if (shippedOrder !== undefined) {
        addStock(stock, shippedOrder.item, shippedOrder.qty);
        delete shipped[id];
        orders[id] = "returned";
        fulfillQueue(queue, pendingWants, stock, reserved, orders);
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

