      }
      if (shipped[event.id] !== undefined) {
        const held = shipped[event.id];
        const back = stock[held.item] === undefined ? 0 : stock[held.item];
        stock[held.item] = back + held.qty;
        delete shipped[event.id];
        orders[event.id] = "returned";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
